#pragma once
#include <stdint.h>

// On-board keyword spotter: log-mel front end + 1D CNN + streaming decoder.
// Plain C++ (no Arduino) so tools/check_cnn.py can compile it on the PC and compare it with PyTorch.
// Weights live in common/cnn_params.h (generated by tools/train_cnn.py).
#define KWS_NM       32      // mel bands
#define KWS_T        42      // frames per CNN window (0.67 s)
#define KWS_STRIDE   4       // the app runs the CNN every 4 frames (64 ms)

// One 16 ms frame (256 int16 samples) -> 32 normalised log-mel values. Same maths as tools/kws.py::logmel.
void kwsMelFrame(const int16_t *psFrame, float *pfOut);

// pfWin: KWS_T rows of KWS_NM normalised log-mel values (time-major, oldest row first).
// pfProb: KWS_NCLASS probabilities (order = kKwsClasses: bg, blue, green, off, on).
void kwsInfer(const float *pfWin, float *pfProb);

// Streaming decoder. Call once per CNN window with its probabilities. Returns the class index (1..) of a keyword
// when one is confirmed, otherwise 0. A keyword peak above KWS_THETA is confirmed after KWS_HOLD windows pass with
// no higher keyword peak; a lower peak inside that time is ignored.
#define KWS_THETA 0.5f
#define KWS_HOLD  3
int  kwsDecode(const float *pfProb);
void kwsDecodeReset();
